.yamb-editable-avatar{--local-orb-user-pic-background:var(--common-bg-secondary);align-items:center;color:var(--common-accent);display:flex;flex-direction:column;position:relative;transition:color 75ms ease-in-out;z-index:1}html.safari .yamb-editable-avatar{will-change:color}.yamb-editable-avatar:hover{color:var(--common-text-primary)}.yamb-editable-avatar__avatar-wrapper{flex-shrink:0;overflow:hidden;position:relative}.yamb-editable-avatar__avatar-wrapper_view_circle{border-radius:100%}.yamb-editable-avatar__avatar-wrapper_view_rounded{border-radius:var(--ui-avatar-rounded-border-radius-xl)}.yamb-editable-avatar__avatar-wrapper_view_square{border-radius:0}.yamb-editable-avatar__overlay{align-items:center;background:var(--common-bg-secondary);bottom:0;cursor:pointer;display:flex;justify-content:center;left:0;position:absolute;right:0;top:0}.yamb-editable-avatar__overlay_hidden{opacity:0}.yamb-editable-avatar__button-text{color:currentColor;cursor:pointer;font-size:var(--font-13-size);font-weight:500;line-height:var(--font-13-line-height);margin-top:var(--spacing-4m);text-align:center}.keyboard-navigation .yamb-editable-avatar__button-text:focus{box-shadow:var(--ui-focus-shadow)}.yamb-editable-avatar_editable .yamb-editable-avatar__button{display:flex}.yamb-editable-avatar__control{cursor:pointer;font-size:0;height:100%;left:0;opacity:0;position:absolute;top:0;width:100%}
